
/**
 * 花朵收集
 */
cc.Class({
    extends: cc.Component,

    properties: {
        red:cc.Node,
        purple:cc.Node,
        blue:cc.Node,
        fly_ui_template:cc.Node,
        _data:null,
    },

    onLoad() {
        this._data = {
            blue:0,
            purple:0,
            red:0,
        }
    },

    start() {
        this.scheduleOnce(()=>{
            this.updateFlower();
            this._initListener();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.updateFlower();
        },this);
    },

    /**
     * 更新花朵信息
     */
    updateFlower() {
        let idx = SlotsFacade.dm.GetBetIdx();
        let freeExtraInfos = SlotsFacade.dm.getDeskInfo().freeExtraInfos;
        let flowerInfo = freeExtraInfos[idx-1];
        if(!flowerInfo) {
            flowerInfo = freeExtraInfos[freeExtraInfos.length-1];
        }
        this._data.blue = flowerInfo.blue.freeCnt;
        this._data.purple = flowerInfo.purple.freeCnt;
        this._data.red = flowerInfo.red.freeCnt;
        this.red.getChildByName("label").getComponent(cc.Label).string = this._data.red.toString();
        this.purple.getChildByName("label").getComponent(cc.Label).string = this._data.purple.toString();
        this.blue.getChildByName("label").getComponent(cc.Label).string = this._data.blue.toString();
    },

    /**
     * 收集花朵
     * @param percent
     */
    async collectFlower() {
        if(!this.node.active) {
            return;
        }
        let petalInfo = SlotsFacade.dm.getSpinData().petalInfo;
        if(!petalInfo || petalInfo.length < 1) {
            return;
        }
        let flowerCfg = {
            "401":{iconIdx:0, flowName:"blue"},
            "402":{iconIdx:1, flowName:"purple"},
            "403":{iconIdx:2, flowName:"red"},
        };
        // 播放收集逻辑
        for(let i=0; i<petalInfo.length; i++) {
            let petal = petalInfo[i];
            let cfgItem = flowerCfg[petal.card];
            if(!cfgItem) {
                continue;
            }
            for(let j=0; j<petal.cnt; j++) {
                SlotsFacade.soundMgr.playEffect("bonus_fly");
                let ui = cc.instantiate(this.fly_ui_template);
                ui.active = true;
                ui.parent = this.node;
                ui.getComponent("ImgSwitchCmp").setIndex(cfgItem.iconIdx);
                let distNode = this[cfgItem.flowName];
                let pos = SlotsFacade.slots.getIdxGlobalPos(petal.idx);
                pos = this.node.convertToNodeSpaceAR(pos);
                ui.setPosition(pos);
                cc.tween(ui)
                    .to(0.5, {x:distNode.x, y:distNode.y})
                    .call(()=>{
                        ui.removeFromParent();
                    })
                    .start();
                await SlotsFacade.delayTime(0.5);
                this._data[cfgItem.flowName]+=1;
                distNode.getChildByName("label").getComponent(cc.Label).string = this._data[cfgItem.flowName].toString();
                let spine = distNode.getChildByName("spine").getComponent(sp.Skeleton);
                spine.setAnimation(0, "animation_3", false);
                spine.addAnimation(0, "animation_2", true);
                await new Promise(res=>{
                    spine.setCompleteListener(()=>{
                        spine.setCompleteListener(null);
                        res();
                    })
                })
            }
        }
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
        this.updateFlower();
    }
});
