
let FlowerCfg = {
    blue:{type:1, blastZoneCnt:1, idleAni:"animation1_1", triggerAni:"animation1_2"},
    purple:{type:2, blastZoneCnt:2, idleAni:"animation2_1", triggerAni:"animation2_2"},
    red:{type:3, blastZoneCnt:3, idleAni:"animation3_1", triggerAni:"animation3_2"},
};
let WheelListCfg = [
    "blue",
    "purple",
    "red",
    "purple",
    "blue"
];
cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        bg:cc.Node,
        wheel:cc.Node,
        items:[cc.Node],
        proxy:cc.Node,  // 用来产生旋转角度数据的节点空节点即可
        spine_result:sp.Skeleton,
        btn_ok:cc.Button,

        _cbHandler:null,
        _canMove:false,
        _wheelCfg:null, // 转轴相关配置
        _data:null,
    },

    onLoad() {
        this._wheelCfg = {
            baseRound:5,                    // 基础旋转圈数
            itemsLen:this.items.length,     // 元素个数
            itemHeight:this.items[0].height,// 单个元素高度
            totalHeight:0,                  // 元素总高度
        }
        this._wheelCfg.totalHeight = this._wheelCfg.itemsLen * this._wheelCfg.itemHeight;

        this.btn_ok.node.on("click", ()=>{
            this.btn_ok.node.stopAllActions();
            this.clickOkBtnEvent();
        }, this)
    },

    clickOkBtnEvent(){
        if(this._canMove) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("wheel_click");
        this._startWheel();
        let spine = this.btn_ok.node.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation1", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            this.btn_ok.node.active = false;
        });
    },

    /**
     * 获取旋转角度
     * @param index
     * @returns {number}
     * @private
     */
    _getRotation(index) {
        let baseRound = this._wheelCfg.baseRound;
        let itemLen = this.items.length;
        let unitAngle = 360/itemLen;  // 单个旋转选项对应的旋转角度
        return baseRound * 360 + index*unitAngle;
    },

    /**
     * 开始旋转
     * @private
     */
    async _startWheel() {
        SlotsFacade.soundMgr.playEffect("wheel_roll2");
        let resultIdx = this._getResult();
        let rotation = this._getRotation(resultIdx);
        this.proxy.rotation = 0;
        let item = this.items[resultIdx+2];
        await new Promise(res=>{
            cc.tween(this.proxy)
                .call(()=> {
                    this._canMove = true;
                })
                .to(7.5, {rotation:rotation}, {easing:"quartInOut"})
                .delay(0.1)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("option");
                    this._canMove = false;
                    this.spine_result.setAnimation(0, "animation", true);
                    item.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, FlowerCfg[item.data.flowerName].triggerAni, true);
                    res();
                })
                .start();
        })
        await SlotsFacade.delayTime(1.5);
        await SlotsFacade.popup.showWinFreeCnt(item.data.freeCnt, true, FlowerCfg[item.data.flowerName].blastZoneCnt);
        this.close();
    },

    /**
     * 更新卷轴
     * @param dt
     */
    update(dt) {
        if(!this._canMove) {
            return;
        }
        let dist = this.proxy.angle%360/360*this._wheelCfg.totalHeight; // 旋转角度转换成移动距离
        for(let i=0; i<this.items.length; i++) {
            let item =this.items[i];
            let originY = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            originY += dist;
            if(originY<-this._wheelCfg.itemHeight/2) {
                originY += this._wheelCfg.totalHeight;
            }
            item.y = originY;
        }
    },

    _getResult() {
        if(this._resultType == 1) {
            return 2;
        }else if(this._resultType == 2) {
            return 1;
        }else if(this._resultType == 3) {
            return 0;
        }
    },

    _initView() {
        // 按钮
        this.btn_ok.node.active = true;
        let spine = this.btn_ok.node.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation", true);
        // items
        for(let i=0; i<this.items.length; i++) {
            let item = this.items[i];
            item.y = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            item.getChildByName("label").getComponent(cc.Label).string = item.data.freeCnt.toString();
            let flowerInfo = FlowerCfg[item.data.flowerName];
            item.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, flowerInfo.idleAni, false);
        }
        // 结果效果
        this.spine_result.setAnimation(0, "animation2", false);
    },

    /**
     * 绑定数据
     * @private
     */
    _bindData() {
        this._canMove = false;
        let freeExtraInfos = SlotsFacade.dm.getDeskInfo().freeExtraInfos;
        let curr = freeExtraInfos[SlotsFacade.dm.GetBetIdx()-1];
        for(let i=0; i<WheelListCfg.length; i++) {
            let item = this.items[i];
            let flowerName = WheelListCfg[i];
            item.data = {flowerName:flowerName, freeCnt:curr[flowerName].freeCnt};
        }
    },

    /**
     * @param resultType:类型1~3-blue~red}
     * @param cb
     */
    async open(resultType, cb) {
        await SlotsFacade.mainPanel.showSceneTransition(2);
        SlotsFacade.soundMgr.playBgm("wheel_bgm");
        this.panel.active = true;
        this._resultType = resultType;
        this._cbHandler = cb;
        this._bindData();
        this._initView();

        cc.vv.gameData.checkAutoPlay(this.btn_ok.node, this.clickOkBtnEvent.bind(this));
    },

    async close() {
        // await SlotsFacade.mainPanel.showSceneTransition(2);
        this.panel.active = false;
        if(this._cbHandler) {
            this._cbHandler();
        }
    }
})