
/**
 * 幸运蜜蜂slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        blast_zone_node:cc.Node,
    },

    onLoad() {
        this._super();
        this.blast_zone_node = this.node.getChildByName("blast_zone_node");
        this.mask = this.node.getChildByName("mask");
    },

    //重写
    StartMove: function () {
        this._super()
        SlotsFacade.flowCtrl.startMove();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    //重写
    onMsgSpine: function (msg) {
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 转换下标
     */
    transferIdx(idx) {
        idx = idx -1;
        let col = idx % this._col
        let row = this._row - Math.floor(idx/this._col) -1;
        return {col:col, row:row};
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx
     */
    getIdxGlobalPos(idx) {
        let idxInfo = this.transferIdx(idx);
        let reel = this._reels[idxInfo.col];
        let pos = reel.GetSymbolPosByRow(idxInfo.row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 设置symbol数据
     * @param cards
     * @constructor
     */
    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {idx:i+1};
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        let spinData = SlotsFacade.dm.getSpinData();
        // 设置水滴数据
        let waterInfo = spinData.waterInfo;
        if(waterInfo) {
            for(let i=0; i<waterInfo.idxs.length; i++) {
                let idxInfo = this.transferIdx(waterInfo.idxs[i]);
                reelResults[idxInfo.col][idxInfo.row].data.waterCnt = waterInfo.cnts[i];
            }
        }
        // 设置bonus数据
        if(spinData.bonusIdxs && spinData.bonusIdxs.length>0) {
            for(let i=0; i<spinData.bonusIdxs.length; i++) {
                let bonusItem = spinData.bonusItems[i];
                if(bonusItem && bonusItem.coin) {
                    let idxInfo = this.transferIdx(spinData.bonusIdxs[i]);
                    reelResults[idxInfo.col][idxInfo.row].data.coin = bonusItem.coin;
                }
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    /**
     * 显示 blast zone 行数
     * @param cnt
     * @param dark 是否播放暗的spine动画 免费和中奖时是播放亮的spine动画
     */
    async showBlastZone(cnt, dark) {
        let spineCfg = [
            {idle:"animation1", idle_dark:"animation1_1", change:"", bg_idle:"animation1_1", bg_change:"animation2_1"},
            {idle:"animation2", idle_dark:"animation1_2", change:"animation2_1", bg_idle:"animation1_2", bg_change:"animation2_1"},
            {idle:"animation3", idle_dark:"animation1_3", change:"animation3_1", bg_idle:"animation1_3", bg_change:"animation3_1"},
        ][cnt-1];
        let spine = this.blast_zone_node.getChildByName("blast").getComponent(sp.Skeleton);
        let spineBg = this.blast_zone_node.getChildByName("blast_bg").getComponent(sp.Skeleton);
        if(cnt > 1) {
            dark = false;
        }
        if(dark) {
            spine.setAnimation(0, spineCfg.idle_dark, true);
            spineBg.setAnimation(0, spineCfg.bg_idle, false);
        }else {
            if(cnt>1) {
                SlotsFacade.soundMgr.playEffect("blastzone_increase");
                spine.setAnimation(0, spineCfg.change, false);
                spine.addAnimation(0, spineCfg.idle, true);
                spineBg.setAnimation(0, spineCfg.bg_change, false);
                spineBg.addAnimation(0, spineCfg.bg_idle, false);
                await new Promise(res=>{
                    spine.setCompleteListener(()=>{
                        spine.setCompleteListener(null);
                        res();
                    });
                });
            }else {
                spine.setAnimation(0, spineCfg.idle, true);
                spineBg.addAnimation(0, spineCfg.bg_idle, false);
            }
        }
    },

    /**
     * 显示遮罩
     */
    showMask() {
        this.mask.active = true;
        this.mask.opacity = 0;
        cc.tween(this.mask)
            .to(0.2, {opacity:140})
            .start();
    },

    /**
     * 隐藏遮罩
     */
    hideMask() {
        if(!this.mask.active) {
            return;
        }
        cc.tween(this.mask)
            .to(0.8, {opacity:0})
            .call(res=>{
                this.mask.active = false;
            })
            .start();
    },

    /**
     * 播放scatter 中奖动画
     */
    async playTriggerAni(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },
});
