cc.Class({
    extends: cc.Component,

    properties:{
        wild_game_title_node:cc.Node,
        wild_node:cc.Node,
        spine_extra_bonus:sp.Skeleton,
        _symbols:[],
        _stickyIdxs:[], // 保存sticky wild idx 数据
        _isEnterWild:false, // 是否进入了wild游戏
    },

    onLoad() {
        this._symbolTemplate = SlotsFacade.dm.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this.wild_node.active = false;
    },

    /////////////////random Wild 相关///////////////
    /**
     * 显示随机wild
     * @param idxs
     * @returns {Promise<void>}
     */
    async showRandomWild() {
        SlotsFacade.slots.showMask();
        await SlotsFacade.delayTime(0.2);
        this.wild_node.active = true;
        // 找出所有wild 的 idx
        let cards = SlotsFacade.dm.getSpinData().resultCards;
        let allWildIdxs = [];
        let gameCfg = SlotsFacade.dm.getGameCfg();
        for(let i=0; i<cards.length; i++) {
            if(gameCfg.wildIds.includes(cards[i])) {
                allWildIdxs.push(i+1);
            }
        }
        // 生成随机wild 的 idx
        let storeInfo = SlotsFacade.dm.energyData;
        let wildIdxs = [];
        for(let i=0; i<storeInfo.freeInfo.randWild; i++) {
            let randomIdx = Math.floor(Math.random()*allWildIdxs.length);
            wildIdxs.push(allWildIdxs[randomIdx]);
            allWildIdxs.splice(randomIdx, 1);
        }
        // 生成随机wild symbol
        for(let i=0; i<wildIdxs.length; i++) {
            let symbol = this.genAWildSymbol(wildIdxs[i], cards[wildIdxs[i]-1]);
            symbol.playStopAnimation();
            this._symbols.push(symbol);
            SlotsFacade.soundMgr.playEffect("symbol_wild");
            await SlotsFacade.delayTime(0.5);
        }
        SlotsFacade.slots.hideMask();
    },

    /////////////////StickyWild 相关///////////////
    /**
     * 添加 sticky wild
     * @private
     */
    _addStickyWild() {
        if(!SlotsFacade.dm.getSpinData()) {
            return;
        }
        let idxs = SlotsFacade.dm.energyData.freeInfo.stickyWild;
        this.wild_node.active = true;
        for(let i=0; i<idxs.length; i++) {
            if(this._stickyIdxs.includes(idxs[i])) {
                continue;
            }
            let symbolId = SlotsFacade.dm.getSpinData().resultCards[idxs[i]-1];
            if(SlotsFacade.dm.getGameCfg().wildIds.includes(symbolId)) {
                let symbol = this.genAWildSymbol(idxs[i], symbolId);
                this._symbols.push(symbol);
                this._stickyIdxs.push(idxs[i]);
            }else {
                console.log("生成sticky wild 失败id异常", SlotsFacade.getSpinData().resultCards, idxs[i]);
            }
        }
    },

    /////////////////extra bonus///////////////
    /**
     * 第一次旋转才需要
     * @returns {Promise<void>}
     */
    async showExtraBonus() {
        SlotsFacade.soundMgr.playEffect("bonus2_increase");
        this.wild_node.active = true;
        for(let i=0; i<20; i++) {
            let idx = 1+Math.floor(Math.random()*30);
            let spine = cc.instantiate(this.spine_extra_bonus.node).getComponent(sp.Skeleton);
            spine.node.parent = this.wild_node;
            spine.node.active = true;
            let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
            pos = this.wild_node.convertToNodeSpaceAR(pos);
            spine.node.setPosition(pos);
            spine.setAnimation(0, "animation", false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                spine.node.removeFromParent();
            })
            await SlotsFacade.delayTime(0.1);
        }
    },

    /////////////////标题控制相关///////////////
    _showTitle() {
        let storeFreeInfo = SlotsFacade.dm.energyData.freeInfo;
        if(!storeFreeInfo) {
            return;
        }
        let typeCfg ={
            "2":"stickyWild",
            "3":"multWild",
            "4":"randWild",
            "5":"removeSymbol",
            "6":"extraBlastZone",
            "7":"extraBonus",
        }
        let needShowTitle = false;
        for(let i=2; i<=7; i++) {
            let contain = storeFreeInfo.hasOwnProperty(typeCfg[i.toString()]);
            if(i == 6) {
                let blast2 = cc.find("store_types/type6_2", this.wild_game_title_node);
                let blast3 = cc.find("store_types/type6_3", this.wild_game_title_node);
                if(contain) {
                    blast2.active = storeFreeInfo.extraBlastZone.length == 2;
                    blast3.active = storeFreeInfo.extraBlastZone.length == 3;
                    needShowTitle = true;
                }else {
                    blast2.active = false;
                    blast3.active = false;
                }
            }else {
                let node = cc.find(`store_types/type${i}`, this.wild_game_title_node);
                if(contain) {
                    node.active = true;
                    needShowTitle = true;
                }else {
                    node.active = false;
                }
            }
        }
        this.wild_game_title_node.active = needShowTitle;

    },
    _hideTile() {
        this.wild_game_title_node.active = false;
    },
    /////////////////wild game 流程相关///////////////
    /**
     * 生成一个wild图标
     * @param {*} idx
     */
    genAWildSymbol(idx, symbolId) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplate)
        node.parent = this.wild_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(0);
        scp.Init(0, this.node);
        scp.ShowById(symbolId);
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return scp;
    },

    /**
     * 进入wild game
     * @returns {Promise<void>}
     */
    async enterWildGame() {
        this._isEnterWild = true;
        this._showTitle();
    },

    /**
     * 退出wild game
     * @returns {Promise<void>}
     */
    async exitWildGame() {
        this.removeWild();
        this._hideTile();
        this._isEnterWild = false;
    },

    /**
     * 移除wild
     */
    removeWild() {
        this._symbols = [];
        this._stickyIdxs = [];
        this.wild_node.active = false;
        this.wild_node.removeAllChildren();
    },

    /**
     * 隐藏wild
     */
    hideWild() {
        this.wild_node.active = false;
    },

    /**
     * 判断 是否有 store 类型
     */
    hasStoreType(storeType) {
        let storeFreeInfo = SlotsFacade.dm.energyData.freeInfo;
        if(!storeFreeInfo) {
            return false;
        }
        let typeCfg ={
            "2":"stickyWild",
            "3":"multWild",
            "4":"randWild",
            "5":"removeSymbol",
            "6":"extraBlastZone",
            "7":"extraBonus",
        }
        return storeFreeInfo.hasOwnProperty(typeCfg[storeType.toString()]);
    },

    /**
     * 开始旋转 还未请求到当局数据
     * @returns {Promise<void>}
     */
    async startMove() {
        let storeInfo = SlotsFacade.dm.energyData;
        if(storeInfo.state != 1) {
            return false;
        }
        if(!this._isEnterWild) {
            return;
        }
        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
            this._addStickyWild();
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
            // 第一次触发需要播放
            if(SlotsFacade.dm.GetFreeTime() == SlotsFacade.dm.GetTotalFree()-1) {
                this.showExtraBonus();
            }
        }
    },

    /**
     * 收到消息
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        let mapInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(mapInfo.state != 1) {
            return;
        }
        if(!this._isEnterWild) {
            return;
        }

        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
            await this.showRandomWild();
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
            if(SlotsFacade.dm.GetFreeTime() == SlotsFacade.dm.GetTotalFree()-1) {
                await SlotsFacade.delayTime(2);
            }
        }
    },

    /**
     * 旋转结束
     * @returns {Promise<void>}
     */
    async spinEnd() {
        let storeInfo = SlotsFacade.dm.energyData;
        // 不在大关直接返回
        if(storeInfo.state != 1) {
            return;
        }
        if(!this._isEnterWild) {
            return;
        }

        let StoreItemType = SlotsFacade.dm.getGameCfg().StoreItemType;
        if(this.hasStoreType(StoreItemType.randWild)) {
            await this.removeWild();
        }else if(this.hasStoreType(StoreItemType.stickyWild)) {
            await this.hideWild();
        }else if(this.hasStoreType(StoreItemType.extraBonus)) {
            await this.hideWild();
        }
    }
 })