
/**
 * 收集进度
 */
cc.Class({
    extends: cc.Component,

    properties: {
        spineBg:sp.Skeleton,                // 背景spine
        label:cc.Label,                     // 水滴数量文本
        icon:cc.Node,                       // 水滴icon
        spineArrive:sp.Skeleton,            // 收集水滴到达时特效
        spineLock:sp.Skeleton,              // 枷锁解锁效果spine
        spineWaterDropTemplate:sp.Skeleton, // 水滴模板

        _isOpen:false,   // 是否打开收集
        _waterDropArr:[], // 保存水滴ui资源
    },

    onLoad() {
        this._initListener();
    },

    start() {
        this.scheduleOnce(()=>{
            this._init();
        });
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.node.on("click", ()=>{
            // 如果在免费中 返回
            if(SlotsFacade.dm.hasFree()) {
                return;
            }
            // 如果spin不可点击 返回
            if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
                return;
            }
            // 自动旋转模式 返回
            if(SlotsFacade.dm.GetAutoModelTime() > 0) {
                return;
            }
            if(this._isOpen) {
                this._openStore();
            }else{
                this._openCollect();
            }
        }, this);
    },

    _init() {
        this.setWaterDropCnt(SlotsFacade.dm.energyData.waterCnt);
        this.showCollect(true);
    },

    _openStore() {
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.storeGame.open(()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy() {
        if(!this._waterDropArr || this._waterDropArr.length<1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("store_fly");
        let endPos = this.icon.getPosition();
        let promiseArr = [];

        this._waterDropArr.forEach(drop =>{
            drop.setAnimation(0, drop.node.endAniName, false);
            promiseArr.push(new Promise(res=> {
                cc.tween(drop.node)
                    .to(0.5, {x: endPos.x, y: endPos.y, scale:1.2}, {easing:"cubicIn"})
                    .call(()=>{
                        drop.node.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        this._waterDropArr = [];
        await SlotsFacade.delayTime(0.5);
        this.setWaterDropCnt(SlotsFacade.dm.energyData.waterCnt, true);
    },

    /**
     * 显示收集界面
     * @param isInit 是否是初始化
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(isInit) {
                this.spineBg.setAnimation(0, "animation1_3", true);
            }else {
                if(!this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("store_unlock");
                    this.spineLock.node.active = true;
                    this.spineLock.setAnimation(0, "animation1", false);
                    this.spineLock.setCompleteListener(()=> {
                        this.spineLock.setCompleteListener(null);
                        this.spineLock.node.active = false;
                    });
                    this.spineBg.setAnimation(0, "animation1_3", true);
                }
            }
            this.icon.color = cc.Color.WHITE;
            this.label.node.color = cc.Color.WHITE;
        }else {
            if(isInit) {
                this.spineBg.setAnimation(0, "animation1_2", true);
            }else {
                if(this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("store_lock");
                    this.spineLock.node.active = true;
                    this.spineLock.setAnimation(0, "animation1_1", false);
                    this.spineLock.setCompleteListener(()=> {
                        this.spineLock.setCompleteListener(null);
                        this.spineLock.node.active = false;
                    });
                    this.spineBg.setAnimation(0, "animation1_2", true);
                }
            }
            this.icon.color = cc.Color.GRAY;
            this.label.node.color = cc.Color.GRAY;
        }
        this._isOpen = boo;
    },

    /**
     * 设置水滴数量
     * @param cnt
     * @param playAni 是否播放动画
     */
    setWaterDropCnt(cnt, playAni) {
        this.label.string = Global.FormatNumToComma(cnt);
        if(playAni) {
            this.spineArrive.node.active = true;
            this.spineArrive.setAnimation(0, "animation", false);
            this.spineArrive.setCompleteListener(()=>{
                this.spineArrive.setCompleteListener(null);
                this.spineArrive.node.active = false;
            });
        }
    },

    /**
     * 添加显示
     * @param val
     * @param globalPos
     */
    addAppearanceDrop(val, globalPos) {
        let drop = cc.instantiate(this.spineWaterDropTemplate.node).getComponent(sp.Skeleton);
        drop.node.active = true;
        drop.node.parent = this.node;
        drop.node.setPosition(this.node.convertToNodeSpaceAR(globalPos));
        let WaterValues = SlotsFacade.dm.getGameCfg().WaterValues;
        let index = WaterValues.indexOf(val);
        if(index == -1) {
            index = 0
        }
        drop.node.startAniName = `animation${WaterValues[index]}_1`;
        drop.node.endAniName = `animation${WaterValues[index]}`;
        drop.setAnimation(0, drop.node.startAniName, false);
        this._waterDropArr.push(drop);
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    }
});
