/**
 * 主场景资源
 */

cc.Class({
    extends: cc.Component,

    properties:{
        panel:cc.Node,
        bg:cc.Node,
        wheel:cc.Node,
        items:[cc.Node],
        proxy:cc.Node,  // 用来产生旋转角度数据的节点空节点即可
        top_ani:cc.Node,

        _cbHandler:null,
        _canMove:false,
        _data:null,
        _itemsCmp:[],
    },

    onLoad() {
        this._symbolTemplete = cc.vv.gameData.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;

        this._wheelCfg = {
            baseRound:9,                    // 基础旋转圈数
            itemsLen:this.items.length,     // 元素个数
            itemHeight:this.items[0].height,// 单个元素高度
            totalHeight:0,                  // 元素总高度
        }
        this._wheelCfg.totalHeight = this._wheelCfg.itemsLen * this._wheelCfg.itemHeight;

        for(let i=0; i<this.items.length; i++) {
            let cmp = this.items[i].addComponent("DwarfsAndPrincess_Symbol");
            cmp.SetSymbolReelIdx(0);
            cmp.Init(0, this.top_ani);
            this._itemsCmp.push(cmp);
        }
    },

    /**
     * 获取旋转角度
     * @param index
     * @returns {number}
     * @private
     */
    _getRotation(index) {
        let baseRound = this._wheelCfg.baseRound;
        if(this.test) {
            baseRound = this.test.round;
        }
        let itemLen = this.items.length;
        let unitAngle = 360/itemLen;  // 单个旋转选项对应的旋转角度
        return baseRound * 360 + index*unitAngle;
    },

    /**
     * 开始旋转
     * @private
     */
    async _startWheel() {
        SlotsFacade.soundMgr.playEffect("wheel_roll");
        this._canMove = true;
        let resultIdx = this._getResult();
        let rotation = this._getRotation(resultIdx);
        this.proxy.rotation = 0;
        let easing = "sineOut";
        if(this.test) {
            easing = this.test.easing;
        }
        await new Promise(res=>{
            cc.tween(this.proxy)
                .call(()=> {
                    this._canMove = true;
                })
                .to(6.1, {rotation:rotation}, {easing:easing})
                .delay(0.1)
                .call(()=>{
                    this._canMove = false;
                    // this._itemsCmp[2].playTriggerAnimation();
                    res();
                })
                .delay(0.6)
                .call(()=>{
                    this._itemsCmp[2].playTriggerAnimation();
                })
                .start();
        })
        // await SlotsFacade.delayTime(1.5);
        this.close();
    },

    /**
     * 更新卷轴
     * @param dt
     */
    update(dt) {
        if(!this._canMove) {
            return;
        }
        let dist = this.proxy.angle%360/360*this._wheelCfg.totalHeight; // 旋转角度转换成移动距离
        for(let i=0; i<this.items.length; i++) {
            let item =this.items[i];
            let originY = this._wheelCfg.itemHeight/2 + i*this._wheelCfg.itemHeight;
            originY += dist;
            if(originY<-this._wheelCfg.itemHeight/2) {
                originY += this._wheelCfg.totalHeight;
            }
            item.y = originY;
        }
    },

    _getResult() {
        return 0;
    },

    /**
     * 绑定数据
     * @private
     */
    _bindData() {
        this._canMove = false;
    },

    /**
     * 初始化ui
     * @param {*} isReconnect 
     */
    _initView() {
        this.panel.active = true;
        this.panel.scale = 0;
        this.bg.active = true;
        this.bg.getComponent("ImgSwitchCmp").setIndex((this._data.idx-1)%5);
        let pos = SlotsFacade.slots.getIdxGlobalPos(this._data.idx);
        pos = this.node.convertToNodeSpaceAR(pos);
        this.panel.setPosition(pos);

        this._itemsCmp[2].StartMove();
        this.top_ani.active = true;
        let wheelData = this._data.item.wheel;
        for(let i=0; i<this._itemsCmp.length; i++) {
            this._itemsCmp[i].StartMove();
            let wheelItemData = wheelData.items[i%wheelData.items.length];
            if(wheelItemData.coin) {
                this._itemsCmp[i].ShowById(wheelItemData.card, {coin:wheelItemData.coin});
            }else {
                this._itemsCmp[i].ShowById(wheelItemData.card);
            }
        }

        /**
         * 设置结果
         */
        this.scheduleOnce(()=>{
            let wheelItemData = wheelData.items[wheelData.resultId-1];
            if(wheelItemData.coin) {
                this._itemsCmp[2].ShowById(wheelItemData.card, {coin:wheelItemData.coin});
            }else {
                this._itemsCmp[2].ShowById(wheelItemData.card);
            }
        }, 1);
    },


    /**
     * 进入游戏
     * @param {{idx:number, item:{}}} data
     * @param data
     * @param callBack
     * @param test 在浏览器console 窗口中调试用
     * @returns {Promise<void>}
     */
    async open(data, callBack, test) {
        this.test = test;
        SlotsFacade.soundMgr.playEffect("symbol_open");
        this._callBack = callBack;
        this._data = data;
        this._bindData();
        this._initView();
        SlotsFacade.slots.showMask();
        cc.tween(this.panel)
            .to(0.6, {scale:1.5}, {easing:"backOut"})
            .start();
        this._startWheel();
    },

    /**
     * 退出游戏
     */
    async close() {
        SlotsFacade.slots.hideMask();
        cc.tween(this.panel)
            .to(0.6, {scale:1}, {easing:"backIn"})
            .call(()=>{
                this.panel.active = false;
                this.top_ani.active = false;
                cc.tween(this.mask)
                    .to(0.5, {opacity:0})
                    .start();
                if(this._callBack) {
                    this._callBack();
                    this._callBack = null;
                }
            })
            .start();
    },
 })