/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal);
            await this.enterFreeGame(true);
        }else {
            SlotsFacade.slots.showBlastZone(1, true);
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 开始移动
     */
    async startMove() {
        SlotsFacade.wildGame.startMove();
    },

    /**
     * 收到spin消息
     * @param {*} msg
     */
    async onSpinMsg(msg) {
        await SlotsFacade.wildGame.onSpinMsg();
        SlotsFacade.slots._gameInfo = msg;
        let cards = msg.resultCards;
        SlotsFacade.slots.SetSlotsResult(cards);
        SlotsFacade.slots.SetReelStateInfo(cards);
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        await SlotsFacade.wildGame.spinEnd();
        // 收集能量
        /*await */this.collectEnergy();
        // 收集花朵
        await SlotsFacade.flowerGame.collectFlower();
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 结算reward
        await this.settleReward();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });

        // await SlotsFacade.delayTime(0.5);
        // 控制按钮
        if (SlotsFacade.dm.isTriggerFree()) {
            if(SlotsFacade.dm.isFistTriggerFree()) {
                await SlotsFacade.slots.playTriggerAni(SlotsFacade.dm.getSpinData().scatterZJLuXian.indexs);
                if(SlotsFacade.dm.currExtraFreeInfo) {
                    SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
                    Global.SlotsSoundMgr.stopBgm();
                    await SlotsFacade.popup.showStartWheel();
                    await new Promise(res=>{
                        SlotsFacade.freeWheelGame.open(SlotsFacade.dm.currExtraFreeInfo.blastZone.length, res);
                    })
                }
                SlotsFacade.slots.Backup();
                await this.enterFreeGame();
            }else {
                await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), false);
            }
        } else if (SlotsFacade.dm.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.stopBgm();
            if(SlotsFacade.dm.energyData.state == 1) {
                if(SlotsFacade.dm.getFreeWinCoin() > 0) {
                    await SlotsFacade.popup.showWinStoreGold(SlotsFacade.dm.getFreeWinCoin());
                }else {
                    await SlotsFacade.popup.showWinStoreZero();
                }
            }else {
                await SlotsFacade.popup.showWinFreeGold(SlotsFacade.dm.getFreeWinCoin());
            }
            await SlotsFacade.mainPanel.showSceneTransition(1);
            SlotsFacade.slots.Resume();
            await this.enterNormalGame();
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame(isReconnect) {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        let freeType = 1;
        let storeInfo = SlotsFacade.dm.energyData;
        if(storeInfo.state == 1) {
            freeType = 2;
        }
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.character.toFreeState();
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = freeType == 1;
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total);
        if(freeType == 2) {
            SlotsFacade.collect.hide();
            await SlotsFacade.wildGame.enterWildGame();
        }else {
            SlotsFacade.collect.show();
        }
        SlotsFacade.flowerGame.hide();
        let blastZoneRow = 1;
        if(SlotsFacade.dm.energyData.freeInfo && SlotsFacade.dm.energyData.freeInfo.hasOwnProperty("extraBlastZone")) {
            blastZoneRow = SlotsFacade.dm.energyData.freeInfo.extraBlastZone.length;
        }else if(SlotsFacade.dm.currExtraFreeInfo && SlotsFacade.dm.currExtraFreeInfo.blastZone) {
            blastZoneRow = SlotsFacade.dm.currExtraFreeInfo.blastZone.length;
        }
        await SlotsFacade.slots.showBlastZone(blastZoneRow, false);
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 进入普通游戏
     */
    async enterNormalGame() {
        SlotsFacade.collect.show();
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.character.toNormalState();
        Global.SlotsSoundMgr.playNormalBgm(true);
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = true;
        SlotsFacade.wildGame.exitWildGame();
        SlotsFacade.flowerGame.show();
        SlotsFacade.slots.showBlastZone(1, true);
        if(SlotsFacade.dm.isLastEndFree()) {
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal, nTotal,true, res);
            });
        }
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        await SlotsFacade.collect.collectEnergy();
    },

    /**
     * 结算 结算 jackpot、蜂巢、金币图标
     * @returns {Promise<void>}
     * @returns {Promise<void>}
     */
    async settleReward() {
        let rewardData = SlotsFacade.dm.getRewardData();
        if(!rewardData) {
            return;
        }
        let sum = 0;
        // 结算honeycombData
        for (const data of rewardData.honeycombData) {
            let symbol = SlotsFacade.slots.GetSymbolByIdx(data.idx);
            symbol.playTriggerAnimation();
            await new Promise(res=>{
                SlotsFacade.miniWheelGame.open(data, res);
            });
            let wheelData = data.item.wheel;
            let wheelItemData = wheelData.items[wheelData.resultId-1];
            let symbolData = {};
            if(wheelItemData.coin) {
                sum += wheelItemData.coin;
                symbolData.coin = wheelItemData.coin;
            }else {
                sum += wheelItemData.jackpot.value;
            }
            symbol.ShowById(wheelItemData.card, symbolData);
            symbol.playTriggerAnimation();
            await new Promise(res=>{
                SlotsFacade.bottomCmp.ShowWin(sum, 1, 0, res);
            });
        }

        // 结算 jackpotData
        for (const data of rewardData.jackpotData) {
            let symbol = SlotsFacade.slots.GetSymbolByIdx(data.idx);
            symbol.playTriggerAnimation();
            await SlotsFacade.delayTime(1);
            await SlotsFacade.popup.showWinJPGold(data.item.jackpot.id, data.item.jackpot.value);
            sum += data.item.jackpot.value;
            await new Promise(res=>{
                SlotsFacade.bottomCmp.ShowWin(sum, 1, 0, res);
            });
        }

        let goldDataCoin = 0;
        // 结算金币图标 bonus
        for (const goldDatum of rewardData.goldData) {
            goldDataCoin += goldDatum.item.coin;
            sum += goldDatum.item.coin;
            let symbol = SlotsFacade.slots.GetSymbolByIdx(goldDatum.idx);
            symbol.playTriggerAnimation();
            SlotsFacade.soundMgr.playEffect("bonus_end_show");
        }
        if(goldDataCoin>0) {
            await SlotsFacade.delayTime(1);
        }
    }
 })