        label.active = true;
        label.scale = 0;
        cc.tween(label)
            .to(0.5, {scale:1})
            .start();
        // 按钮
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.scale = 0;
        okBtn.active = true;
        cc.tween(okBtn)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        let spine = panel.getChildByName("spine").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation", false);
        spine.addAnimation(0, "animation_1", true);

        await SlotsFacade.delayTime(0.9);
