let SelectorType = { // 选择器类型
    count:1,    // 次数类型
    remove:2,   // 移除类型
    blast_zone:3,// 爆炸区域类型
    mul_wild:4, //多wild类型
};
cc.Class({
    extends: cc.Component,

    properties: {
        state_close:cc.Node,
        state_open:cc.Node,
        costLabel:cc.Label,

        id:0,
        _storeItemCfg:null,
        _handler:null,
        _activeSelector:[]
    },

    onLoad () {
        this.state_close = this.node.getChildByName("state_close");
        this.state_close.active = true;
        this.state_close.on("click", this.open, this);
        this.state_open = this.node.getChildByName("state_open");
        this.state_open.active = false;
        this.costLabel = cc.find("cost/label", this.state_open).getComponent(cc.Label);
    },

    onDestroy() {
        this._storeItemCfg = null;
        this._handler = null;
    },

    start() {
        // 初始化标题
        this.state_close.getChildByName("title").getComponent("ImgSwitchCmp").setIndex(this._storeItemCfg.titleIndex);
        this.state_open.getChildByName("title").getComponent("ImgSwitchCmp").setIndex(this._storeItemCfg.titleIndex);

        // 初始化参数设置选项
        for(let i=0; i<4; i++) {
            let selector = cc.find(`selector_node/selector${i+1}`, this.state_open);
            let selectorType = i+1;
            let typeCfg = null;
            for(let j=0; j<this._storeItemCfg.types.length; j++) {
                if(this._storeItemCfg.types[j].selectorType == selectorType) {
                    typeCfg = this._storeItemCfg.types[j];
                    break;
                }
            }
            if(typeCfg) {
                selector.active = true;
            }else {
                selector.active = false;
            }
            if(!selector.active) {
                continue;
            }
            selector.data = {
                storeType:typeCfg.type,
                selectorType: i+1,
                mults:typeCfg.mults.concat(),
                info:typeCfg.info.concat(),
                currSelectIndex:0
            }
            let minusBtn = selector.getChildByName("btn_minus").getComponent(cc.Button);
            minusBtn.node.on("click", () => {
                this._changeParam(selector, -1);
            }, this);
            let plusBtn = selector.getChildByName("btn_plus").getComponent(cc.Button);
            plusBtn.node.on("click", () => {
                this._changeParam(selector, 1);
            }, this);
            this._activeSelector.push(selector);
        }
        this._reset();
    },

    /**
     * 选择参数变化
      * @param selector
     * @param val
     * @private
     */
    _changeParam(selector, val) {
        let data = selector.data;
        data.currSelectIndex += val;
        if(data.currSelectIndex<0) {
            data.currSelectIndex = 0;
        }else if(data.currSelectIndex>=data.info.length) {
            data.currSelectIndex = data.info.length-1;
        }
        this._updateOpenState();
        this._handler({evt:"change", target:this});
    },

    init(storeItemCfg, handler) {
        this._storeItemCfg = storeItemCfg;
        this._handler = handler;
    },

    open() {
        this.state_close.active = false;
        this.state_open.active = true;
        this._handler({evt:"open", target:this});
    },

    close() {
        this.state_close.active = true;
        this.state_open.active = false;
        this._reset();
    },

    _updateOpenState() {
        SlotsFacade.soundMgr.playEffect("click");
        for(let i=0; i<this._activeSelector.length; i++) {
            let selector = this._activeSelector[i];
            let data = selector.data;
            switch (data.selectorType) {
                case SelectorType.count:
                    selector.getChildByName("label").getComponent(cc.Label).string = data.info[data.currSelectIndex];
                    break;
                case SelectorType.remove:
                    let children = selector.getChildByName("label").children;
                    for(let c of children) {
                        c.active = data.info[data.currSelectIndex].includes(parseInt(c.name));
                    }
                    break;
                case SelectorType.blast_zone:
                    selector.getChildByName("label").getComponent("ImgSwitchCmp").setIndex(data.currSelectIndex);
                    break;
                case SelectorType.mul_wild:
                    selector.getChildByName("label").getComponent("ImgSwitchCmp").setIndex(data.currSelectIndex);
                    break;
            }
            selector.getChildByName("btn_minus").getComponent(cc.Button).interactable = data.currSelectIndex != 0;
            selector.getChildByName("btn_plus").getComponent(cc.Button).interactable = data.currSelectIndex < data.info.length-1;
        }
    },

    _reset() {
        for(let i=0; i<this._activeSelector.length; i++) {
            this._activeSelector[i].data.currSelectIndex = 0;
        }
        this._updateOpenState();
    },

    /**
     * 获取 选择的倍数
     */
    getMultiple() {
        let mul = 1;
        for(let i=0; i<this._activeSelector.length; i++) {
            let  data = this._activeSelector[i].data;
            mul *= data.mults[data.currSelectIndex];
        }
        return mul;
    },

    /**
     * 获取请求参数
     */
    getReqParam() {
        let ret = [];
        for(let i=0; i<this._activeSelector.length; i++) {
            let  data = this._activeSelector[i].data;
            ret.push({
                type:data.storeType,
                mult:data.mults[data.currSelectIndex]
            })
        }
        return ret;
    },

    /**
     * 设置消耗水滴数量
     * @param val
     */
    setCost(val) {
        this.costLabel.string = val.toString();
    }
});
